#!/usr/bin/env wolframscript
(* fit.wls -- usage: fit.wls data.csv *)
data = Import[$ScriptCommandLine[[2]], "CSV"];
model = LinearModelFit[data, x, x];
Print[Normal[model]];
Export["fit.json", <|"coeffs" -> model["BestFitParameters"], "r2" -> model["RSquared"]|>];
Exit[0]

link = LinkLaunch[First[$CommandLine] <> " -wstp"];
LinkWrite[link, Unevaluated[EvaluatePacket[Prime[100]]]];
LinkRead[link]
LinkClose[link]

session = StartExternalSession["Python"];
ExternalEvaluate[session, "import numpy as np; np.linalg.det([[1,2],[3,4]])"]
f = ExternalFunction[session, "lambda x: x**2 + 1"];
f /@ Range[5]
DeleteObject[session]
